glsl3.vert:
precision highp float;
uniform CCGlobal {
  vec4 cc_time;

  vec4 cc_screenSize;

  vec4 cc_screenScale;

  vec4 cc_nativeSize;

  mat4 cc_matView;
  mat4 cc_matViewInv;
  mat4 cc_matProj;
  mat4 cc_matProjInv;
  mat4 cc_matViewProj;
  mat4 cc_matViewProjInv;
  vec4 cc_cameraPos;

  vec4 cc_exposure;

  vec4 cc_mainLitDir;

  vec4 cc_mainLitColor;

  vec4 cc_ambientSky;
  vec4 cc_ambientGround;
};
uniform CCLocal {
  mat4 cc_matWorld;
  mat4 cc_matWorldIT;
};

in vec3 a_position;
in vec4 a_color;
out vec4 v_color;

#if USE_TEXTURE
in vec2 a_uv0;
out vec2 v_uv0;
#endif

void main () {
  vec4 pos = vec4(a_position, 1.0);
  pos = cc_matViewProj * pos;
  #if USE_TEXTURE
  v_uv0 = a_uv0;
  #endif
  v_color = a_color;
  gl_Position = pos;
}

glsl3.frag:
precision highp float;

in vec4 v_color;

#if USE_TEXTURE
in vec2 v_uv0;
uniform sampler2D texture;
uniform sampler2D flipbookTex;
uniform sampler2D colorFlipbookTex;
#endif

uniform PROPERTIES {
  vec4 uvRect;
  vec4 directAtlasRect;
  vec4 flipbookSourceCropRect;
  vec4 colorFlipbookSourceCropRect;
  vec4 flipbookAtlasSize;
  vec4 colorFlipbookAtlasSize;
  vec4 flipbookAtlasPadding;
  vec4 flipbookMaskRemap;
  vec4 cardCutoutRect;
  vec4 maskInnerColor;
  vec4 maskOuterColor;
  float time;
  float flipbookFrameCount;
  float flipbookTileX;
  float flipbookTileY;
  float flipbookChannelPacked;
  float flipbookDurationMs;
  float flipbookDelayMs;
  float flipbookLoop;
  float flipbookFrameIntervalMs;
  float flipbookSegmentedLoop;
  float flipbookLoopStartFrame;
  float flipbookLoopFrameCount;
  float flipbookLoopFrameIntervalMs;
  float flipbookLoopStartMs;
  float flipbookOpacity;
  float sampleCurrentTexture;
  float directAtlasSample;
  float cardCutoutEnabled;
  float cardCutoutSoftness;
  float packedEnergyColorizeEnabled;
  float colorAdjustEnabled;
  float hueShift;
  float saturationMul;
  float valueMul;
  float contrastMul;
  float colorAdjustStrength;
  float colorAdjustWhiteProtect;
  float colorAdjustMode;
  float colorFlipbookFrameCount;
  float colorFlipbookFrameStart;
  float colorFlipbookTileX;
  float colorFlipbookTileY;
  float colorFlipbookChannelPacked;
  float colorMix;
};

float getFlipbookCellIndexEx(float frameIdx, float channelPacked) {
  if (channelPacked > 0.5) {
    return floor(frameIdx / 4.0);
  }
  return frameIdx;
}

float getFlipbookCellIndex(float frameIdx) {
  return getFlipbookCellIndexEx(frameIdx, flipbookChannelPacked);
}

vec4 getFlipbookChannelEx(float frameIdx, float channelPacked) {
  if (channelPacked < 0.5) {
    return vec4(1.0);
  }
  float ch = mod(frameIdx, 4.0);
  if (ch < 0.5) {
    return vec4(1.0, 0.0, 0.0, 0.0);
  }
  if (ch < 1.5) {
    return vec4(0.0, 1.0, 0.0, 0.0);
  }
  if (ch < 2.5) {
    return vec4(0.0, 0.0, 1.0, 0.0);
  }
  return vec4(0.0, 0.0, 0.0, 1.0);
}

vec4 getFlipbookChannel(float frameIdx) {
  return getFlipbookChannelEx(frameIdx, flipbookChannelPacked);
}

vec2 clampAtlasLocalUv(vec2 localUv, float tileX, float tileY, vec4 atlasSize, float paddingPx) {
  float safeTileX = max(1.0, floor(tileX + 0.5));
  float safeTileY = max(1.0, floor(tileY + 0.5));
  vec2 safeAtlasSize = max(atlasSize.xy, vec2(safeTileX * 2.0, safeTileY * 2.0));
  vec2 cellPx = max(vec2(1.0, 1.0), safeAtlasSize / vec2(safeTileX, safeTileY));
  vec2 halfTexel = 0.5 / cellPx;
  vec2 padUv = min(vec2(max(0.0, paddingPx)) / cellPx, vec2(0.45, 0.45));
  vec2 minUv = padUv + halfTexel;
  vec2 maxUv = vec2(1.0, 1.0) - padUv - halfTexel;
  return mix(minUv, maxUv, clamp(localUv, 0.0, 1.0));
}

vec2 getFlipbookAtlasUvEx(float frameIdx, vec2 localUv, float tileX, float tileY, float channelPacked, vec4 atlasSize, float paddingPx) {
  float safeTileX = max(1.0, floor(tileX + 0.5));
  float safeTileY = max(1.0, floor(tileY + 0.5));
  float cellIdx = getFlipbookCellIndexEx(frameIdx, channelPacked);
  float col = mod(cellIdx, safeTileX);
  float row = floor(cellIdx / safeTileX);
  float rowClamped = clamp(row, 0.0, safeTileY - 1.0);
  vec2 cell = vec2(1.0 / safeTileX, 1.0 / safeTileY);
  vec2 safeLocalUv = clampAtlasLocalUv(localUv, safeTileX, safeTileY, atlasSize, paddingPx);
  return vec2(
    (col + safeLocalUv.x) * cell.x,
    (rowClamped + safeLocalUv.y) * cell.y
  );
}

vec2 getFlipbookAtlasUv(float frameIdx, vec2 localUv, float tileX, float tileY) {
  return getFlipbookAtlasUvEx(frameIdx, localUv, tileX, tileY, flipbookChannelPacked, flipbookAtlasSize, flipbookAtlasPadding.x);
}

float remapPackedEnergyAlpha(float alpha) {
  float energyAlpha = clamp(alpha, 0.0, 1.0);

  if (flipbookMaskRemap.y >= 0.5) {
    return energyAlpha;
  }
  float low = clamp(flipbookAtlasPadding.z, 0.0, 0.98);
  float high = clamp(max(flipbookAtlasPadding.w, low + 0.001), 0.001, 1.0);
  float remapped = smoothstep(low, high, energyAlpha);
  float gammaValue = max(0.001, flipbookMaskRemap.x);
  return pow(remapped, gammaValue);
}

vec2 getSourceUvFromSpriteUv(vec2 localUv) {
  return localUv;
}

float getSourceCropMaskForRect(vec2 sourceUv, vec4 cropRect) {
  vec2 cropMin = clamp(cropRect.xy, vec2(0.0, 0.0), vec2(1.0, 1.0));
  vec2 cropMax = clamp(cropRect.xy + max(cropRect.zw, vec2(0.0001, 0.0001)),
    vec2(0.0, 0.0), vec2(1.0, 1.0));
  vec2 insideMin = step(cropMin, sourceUv);
  vec2 insideMax = step(sourceUv, cropMax);
  return insideMin.x * insideMin.y * insideMax.x * insideMax.y;
}

vec2 getAtlasLocalUvFromSourceUvForRect(vec2 sourceUv, vec4 cropRect) {
  vec2 cropMin = clamp(cropRect.xy, vec2(0.0, 0.0), vec2(1.0, 1.0));
  vec2 cropSize = max(cropRect.zw, vec2(0.0001, 0.0001));
  return clamp((sourceUv - cropMin) / cropSize, vec2(0.0, 0.0), vec2(1.0, 1.0));
}

float getSourceCropMask(vec2 sourceUv) {
  return getSourceCropMaskForRect(sourceUv, flipbookSourceCropRect);
}

vec2 getAtlasLocalUvFromSourceUv(vec2 sourceUv) {
  return getAtlasLocalUvFromSourceUvForRect(sourceUv, flipbookSourceCropRect);
}

vec4 sampleFlipbookFrame(float frameIdx, vec2 localUv, float tileX, float tileY) {
  vec2 sourceUv = getSourceUvFromSpriteUv(localUv);
  float cropMask = getSourceCropMask(sourceUv);
  vec2 atlasLocalUv = getAtlasLocalUvFromSourceUv(sourceUv);
  vec4 texel = texture2D(flipbookTex, getFlipbookAtlasUv(frameIdx, atlasLocalUv, tileX, tileY));
  if (flipbookChannelPacked < 0.5) {
    return texel * cropMask;
  }
  float value = dot(texel, getFlipbookChannel(frameIdx));
  value = remapPackedEnergyAlpha(value);
  return vec4(vec3(value), value) * cropMask;
}

vec4 sampleColorFlipbookFrame(float frameIdx, vec2 localUv) {
  float safeSegmentFrameCount = max(1.0, floor(colorFlipbookFrameCount + 0.5));
  float safeFrameStart = max(0.0, floor(colorFlipbookFrameStart + 0.5));
  float safeLocalIdx = clamp(frameIdx, 0.0, safeSegmentFrameCount - 1.0);
  float safeFrameIdx = safeFrameStart + safeLocalIdx;
  vec2 sourceUv = getSourceUvFromSpriteUv(localUv);
  float cropMask = getSourceCropMaskForRect(sourceUv, colorFlipbookSourceCropRect);
  vec2 atlasLocalUv = getAtlasLocalUvFromSourceUvForRect(sourceUv, colorFlipbookSourceCropRect);
  vec4 texel = texture2D(colorFlipbookTex, getFlipbookAtlasUvEx(safeFrameIdx, atlasLocalUv,
    max(1.0, colorFlipbookTileX), max(1.0, colorFlipbookTileY), colorFlipbookChannelPacked, colorFlipbookAtlasSize, flipbookAtlasPadding.y));
  if (colorFlipbookChannelPacked < 0.5) {
    return texel * cropMask;
  }
  float value = dot(texel, getFlipbookChannelEx(safeFrameIdx, colorFlipbookChannelPacked));
  return vec4(vec3(value), value) * cropMask;
}

vec3 rgbToYiq(vec3 rgb) {
  return vec3(
    dot(rgb, vec3(0.299, 0.587, 0.114)),
    dot(rgb, vec3(0.596, -0.274, -0.322)),
    dot(rgb, vec3(0.211, -0.523, 0.312))
  );
}

vec3 yiqToRgb(vec3 yiq) {
  return clamp(vec3(
    yiq.x + 0.956 * yiq.y + 0.621 * yiq.z,
    yiq.x - 0.272 * yiq.y - 0.647 * yiq.z,
    yiq.x - 1.106 * yiq.y + 1.703 * yiq.z
  ), 0.0, 1.0);
}

vec3 applyPsHueYiq(vec3 rgb, float hueShiftVal) {
  vec3 yiq = rgbToYiq(max(rgb, vec3(0.0)));
  float chroma = length(yiq.yz);
  float hue = chroma > 1.0e-5 ? atan(yiq.z, yiq.y) : 0.0;
  hue += hueShiftVal * 6.28318530718;
  yiq.yz = vec2(cos(hue), sin(hue)) * chroma;
  return yiqToRgb(yiq);
}

vec3 applyPsSaturationRec709(vec3 rgb, float sat) {
  float s = max(0.0, sat);
  vec3 safe = max(rgb, vec3(0.0));
  float luma = dot(safe, vec3(0.2125, 0.7154, 0.0721));
  return mix(vec3(luma), safe, s);
}

float bakedRec709Luminance(vec3 rgb) {
  return dot(max(rgb, vec3(0.0)), vec3(0.2126, 0.7152, 0.0722));
}

float calcHighlightPreserveMask(float bright, float protect) {
  float band = mix(0.02, 0.08, clamp(protect, 0.0, 2.0) * 0.5);
  return smoothstep(1.0 - band, 1.0, clamp(bright, 0.0, 1.0));
}

vec3 applyHighlightPreservingValueScale(vec3 sourceRgb, float valueMul, float strength) {
  float s = clamp(strength, 0.0, 1.0);
  float mul = max(0.0, valueMul);
  vec3 safe = max(sourceRgb, vec3(0.0));
  if (s <= 0.00001 || abs(mul - 1.0) <= 0.00001) {
    return safe;
  }
  float protect = clamp(colorAdjustWhiteProtect, 0.0, 2.0);
  if (protect <= 0.00001) {
    return mix(safe, clamp(safe * mul, 0.0, 1.0), s);
  }
  float luma = bakedRec709Luminance(safe);
  float peak = max(max(safe.r, safe.g), safe.b);
  float bright = max(luma, peak);
  float preserve = calcHighlightPreserveMask(bright, protect);
  float yScaled = clamp(luma * mul, 0.0, 1.0);
  vec3 chroma = safe - luma;
  vec3 adjusted = clamp(yScaled + chroma, 0.0, 1.0);
  vec3 preserved = mix(adjusted, safe, preserve);
  return mix(safe, preserved, s);
}

vec3 applyRuntimeBakedHueSatAdjust(vec3 sourceRgb) {
  float strength = clamp(colorAdjustStrength, 0.0, 1.0);
  vec3 safe = max(sourceRgb, vec3(0.0));
  vec3 hued = applyPsHueYiq(safe, hueShift);
  vec3 satd = applyPsSaturationRec709(hued, saturationMul);
  return mix(safe, satd, strength);
}

vec3 applyRuntimeBakedContrastAdjust(vec3 sourceRgb) {
  float s = clamp(colorAdjustStrength, 0.0, 1.0);
  float mul = max(0.0, contrastMul);
  vec3 safe = max(sourceRgb, vec3(0.0));
  if (s <= 0.00001 || abs(mul - 1.0) <= 0.00001) {
    return safe;
  }
  float luma = bakedRec709Luminance(safe);
  float newLuma = clamp((luma - 0.5) * mul + 0.5, 0.0, 1.0);
  vec3 contrasted = clamp(vec3(newLuma) + (safe - luma), 0.0, 1.0);
  return mix(safe, contrasted, s);
}

vec3 applyRuntimeBakedValueAdjust(vec3 sourceRgb) {
  if (colorAdjustMode > 0.5) {
    float strength = clamp(colorAdjustStrength, 0.0, 1.0);
    vec3 safe = max(sourceRgb, vec3(0.0));
    if (strength <= 0.00001 || abs(valueMul - 1.0) <= 0.00001) {
      return safe;
    }
    vec3 adj = clamp(safe + vec3(valueMul - 1.0), 0.0, 1.0);
    return mix(safe, adj, strength);
  }
  return applyHighlightPreservingValueScale(sourceRgb, valueMul, colorAdjustStrength);
}

float sampleFlipbookEnergy(float frameIdx, vec2 localUv, float tileX, float tileY) {
  return sampleFlipbookFrame(frameIdx, localUv, tileX, tileY).a;
}

vec3 applyLobeGradientDetail(vec3 rgb, float energy, vec2 localUv, float frameIdx0, float frameIdx1, float frameBlend, float tileX, float tileY) {
  vec2 atlasCell = max(flipbookAtlasSize.xy / vec2(max(1.0, tileX), max(1.0, tileY)), vec2(1.0));
  vec2 texel = vec2(1.0) / atlasCell;
  float eL = mix(sampleFlipbookEnergy(frameIdx0, localUv - vec2(texel.x, 0.0), tileX, tileY),
    sampleFlipbookEnergy(frameIdx1, localUv - vec2(texel.x, 0.0), tileX, tileY), frameBlend);
  float eR = mix(sampleFlipbookEnergy(frameIdx0, localUv + vec2(texel.x, 0.0), tileX, tileY),
    sampleFlipbookEnergy(frameIdx1, localUv + vec2(texel.x, 0.0), tileX, tileY), frameBlend);
  float eB = mix(sampleFlipbookEnergy(frameIdx0, localUv - vec2(0.0, texel.y), tileX, tileY),
    sampleFlipbookEnergy(frameIdx1, localUv - vec2(0.0, texel.y), tileX, tileY), frameBlend);
  float eT = mix(sampleFlipbookEnergy(frameIdx0, localUv + vec2(0.0, texel.y), tileX, tileY),
    sampleFlipbookEnergy(frameIdx1, localUv + vec2(0.0, texel.y), tileX, tileY), frameBlend);
  float grad = (abs(eR - eL) + abs(eT - eB)) * 0.5;
  float lobe = smoothstep(0.025, 0.15, grad) * smoothstep(0.15, 0.85, energy);
  vec3 detail = mix(maskOuterColor.rgb, maskInnerColor.rgb, 0.42);
  vec3 brightened = max(rgb, detail * 0.85);
  return mix(brightened, detail, lobe * 0.38);
}

vec3 colorizePackedEnergy(float energy) {
  float edge = smoothstep(0.012, 0.14, energy);
  float mid = smoothstep(0.08, 0.50, energy);
  float inner = smoothstep(0.30, 0.68, energy);
  float core = smoothstep(0.76, 0.94, energy);
  vec3 edgeRgb = maskOuterColor.rgb * 0.35;
  vec3 midRgb = mix(maskOuterColor.rgb, maskInnerColor.rgb, 0.48);
  vec3 innerRgb = mix(maskInnerColor.rgb, vec3(1.0), 0.32);
  vec3 coreRgb = vec3(1.0);
  vec3 rgb = mix(edgeRgb, midRgb, mid);
  rgb = mix(rgb, innerRgb, inner);
  rgb = mix(rgb, coreRgb, core * 0.58);
  return rgb * max(edge, 0.90);
}

void main() {
  vec2 uvSize = max(uvRect.zw, vec2(0.0001, 0.0001));
  vec2 localUv = clamp((v_uv0 - uvRect.xy) / uvSize, 0.0, 1.0);
  float safeFrameCount = max(1.0, floor(flipbookFrameCount + 0.5));
  float safeTileX = max(1.0, floor(flipbookTileX + 0.5));
  float safeTileY = max(1.0, floor(flipbookTileY + 0.5));
  float safeDurationSec = max(0.001, flipbookDurationMs * 0.001);
  float delaySec = max(0.0, flipbookDelayMs * 0.001);
  if (time < delaySec) {
    discard;
  }

  float elapsedSec = max(0.0, time - delaySec);
  float frameFloat = 0.0;
  float frameIdx0 = 0.0;
  float frameIdx1 = 0.0;
  float loopStart = clamp(floor(flipbookLoopStartFrame + 0.5), 0.0, safeFrameCount - 1.0);
  float loopCount = clamp(floor(flipbookLoopFrameCount + 0.5), 0.0, safeFrameCount - loopStart);
  float intervalMs = max(1.0, flipbookFrameIntervalMs);
  if (flipbookSegmentedLoop > 0.5 && loopCount > 1.0) {
    float elapsedMs = elapsedSec * 1000.0;
    float loopStartMs = flipbookLoopStartMs > 0.0 ? flipbookLoopStartMs : loopStart * intervalMs;
    float loopIntervalMs = max(1.0, flipbookLoopFrameIntervalMs);
    if (elapsedMs < loopStartMs || loopStart < 1.0) {
      float introLast = max(0.0, loopStart - 1.0);
      frameFloat = clamp(elapsedMs / intervalMs, 0.0, introLast);
      frameIdx0 = clamp(floor(frameFloat), 0.0, safeFrameCount - 1.0);
      frameIdx1 = clamp(ceil(frameFloat), 0.0, safeFrameCount - 1.0);
    } else {
      float loopFrameFloat = max(0.0, elapsedMs - loopStartMs) / loopIntervalMs;
      float loopBase = mod(floor(loopFrameFloat), loopCount);
      frameFloat = loopStart + loopBase + fract(loopFrameFloat);
      frameIdx0 = loopStart + loopBase;
      frameIdx1 = loopStart + mod(loopBase + 1.0, loopCount);
    }
  } else if (flipbookLoop > 0.5 && loopCount > 1.0) {

    float elapsedMs = elapsedSec * 1000.0;
    float loopIntervalMs = max(1.0, flipbookLoopFrameIntervalMs > 0.0 ? flipbookLoopFrameIntervalMs : intervalMs);
    float periodFrames = min(loopCount, safeFrameCount);
    float loopFrameFloat = elapsedMs / loopIntervalMs;
    float loopBase = mod(floor(loopFrameFloat), periodFrames);
    frameFloat = loopBase + fract(loopFrameFloat);
    frameIdx0 = mod(loopBase, safeFrameCount);
    frameIdx1 = mod(loopBase + 1.0, safeFrameCount);
  } else {

    float elapsedMs = elapsedSec * 1000.0;
    frameFloat = clamp(elapsedMs / intervalMs, 0.0, safeFrameCount - 1.0);
    frameIdx0 = clamp(floor(frameFloat), 0.0, safeFrameCount - 1.0);
    frameIdx1 = clamp(ceil(frameFloat), 0.0, safeFrameCount - 1.0);
  }
  float frameBlend = fract(frameFloat);
  vec4 frame0 = sampleFlipbookFrame(frameIdx0, localUv, safeTileX, safeTileY);
  vec4 frame1 = sampleFlipbookFrame(frameIdx1, localUv, safeTileX, safeTileY);
  float blendedAlpha = mix(frame0.a, frame1.a, frameBlend);
  vec3 premulRgb = mix(frame0.rgb * frame0.a, frame1.rgb * frame1.a, frameBlend);
  vec4 flipbookColor = vec4(premulRgb / max(blendedAlpha, 0.0001), blendedAlpha) * v_color;
  if (directAtlasSample > 0.5) {
    vec2 directUv = directAtlasRect.xy + localUv * max(directAtlasRect.zw, vec2(0.0001, 0.0001));
    flipbookColor = texture2D(flipbookTex, directUv) * v_color;
  }
  if (sampleCurrentTexture > 0.5) {
    flipbookColor = texture2D(texture, v_uv0);
    #if CC_USE_ALPHA_ATLAS_TEXTURE
      flipbookColor.a *= texture2D(texture, v_uv0 + vec2(0.0, 0.5)).r;
    #endif
    flipbookColor *= v_color;
  }
  float flameEnergy = -1.0;
  if (flipbookChannelPacked > 0.5 && flipbookColor.a > 0.001) {
    flameEnergy = clamp(flipbookColor.a, 0.0, 1.0);
  }
  if (packedEnergyColorizeEnabled > 0.5 && flameEnergy >= 0.0) {
    vec3 packedRgb = colorizePackedEnergy(flameEnergy);
    packedRgb = applyLobeGradientDetail(packedRgb, flameEnergy, localUv, frameIdx0, frameIdx1, frameBlend, safeTileX, safeTileY);
    flipbookColor.rgb = packedRgb * v_color.rgb;
  }
  if (colorAdjustEnabled > 0.5 && flipbookColor.a > 0.001) {
    flipbookColor.rgb = applyRuntimeBakedHueSatAdjust(flipbookColor.rgb);
  }
  if (colorMix > 0.001) {
    vec4 color0 = sampleColorFlipbookFrame(frameIdx0, localUv);
    vec4 color1 = sampleColorFlipbookFrame(frameIdx1, localUv);
    float colorAlpha = mix(color0.a, color1.a, frameBlend);
    vec3 colorRgb = mix(color0.rgb * color0.a, color1.rgb * color1.a, frameBlend) / max(colorAlpha, 0.0001);
    vec4 colorSample = vec4(colorRgb, colorAlpha) * v_color;
    if (colorAdjustEnabled > 0.5 && colorSample.a > 0.001) {
      colorSample.rgb = applyRuntimeBakedHueSatAdjust(colorSample.rgb);
    }
    float colorAlphaWeight = smoothstep(0.002, 0.08, colorSample.a)
      * smoothstep(0.002, 0.08, flipbookColor.a);
    flipbookColor.rgb = mix(flipbookColor.rgb, colorSample.rgb, clamp(colorMix, 0.0, 1.0) * colorAlphaWeight);
  }
  if (colorAdjustEnabled > 0.5 && flipbookColor.a > 0.001) {
    flipbookColor.rgb = applyRuntimeBakedContrastAdjust(flipbookColor.rgb);
  }
  if (colorAdjustEnabled > 0.5 && flipbookColor.a > 0.001) {
    flipbookColor.rgb = applyRuntimeBakedValueAdjust(flipbookColor.rgb);
  }
  float outAlpha = flipbookColor.a * clamp(flipbookOpacity, 0.0, 1.0);
  if (cardCutoutEnabled > 0.5) {
    vec2 cutMin = clamp(cardCutoutRect.xy, vec2(0.0, 0.0), vec2(1.0, 1.0));
    vec2 cutMax = clamp(cardCutoutRect.xy + cardCutoutRect.zw, vec2(0.0, 0.0), vec2(1.0, 1.0));
    float soft = max(0.0001, cardCutoutSoftness);
    float insideX = smoothstep(cutMin.x - soft, cutMin.x + soft, localUv.x)
      * (1.0 - smoothstep(cutMax.x - soft, cutMax.x + soft, localUv.x));
    float insideY = smoothstep(cutMin.y - soft, cutMin.y + soft, localUv.y)
      * (1.0 - smoothstep(cutMax.y - soft, cutMax.y + soft, localUv.y));
    outAlpha *= (1.0 - insideX * insideY);
  }
  if (outAlpha <= 0.001) {
    discard;
  }

  vec4 outColor = vec4(flipbookColor.rgb, outAlpha);
  gl_FragColor = outColor;
}

glsl1.vert:
precision highp float;
uniform mat4 cc_matViewProj;

attribute vec3 a_position;
attribute vec4 a_color;
varying vec4 v_color;

#if USE_TEXTURE
attribute vec2 a_uv0;
varying vec2 v_uv0;
#endif

void main () {
  vec4 pos = vec4(a_position, 1.0);
  pos = cc_matViewProj * pos;
  #if USE_TEXTURE
  v_uv0 = a_uv0;
  #endif
  v_color = a_color;
  gl_Position = pos;
}

glsl1.frag:
precision highp float;

varying vec4 v_color;

#if USE_TEXTURE
varying vec2 v_uv0;
uniform sampler2D texture;
uniform sampler2D flipbookTex;
uniform sampler2D colorFlipbookTex;
#endif

uniform vec4 uvRect;
uniform vec4 directAtlasRect;
uniform vec4 flipbookSourceCropRect;
uniform vec4 colorFlipbookSourceCropRect;
uniform vec4 flipbookAtlasSize;
uniform vec4 colorFlipbookAtlasSize;
uniform vec4 flipbookAtlasPadding;
uniform vec4 flipbookMaskRemap;
uniform vec4 cardCutoutRect;
uniform vec4 maskInnerColor;
uniform vec4 maskOuterColor;
uniform float time;
uniform float flipbookFrameCount;
uniform float flipbookTileX;
uniform float flipbookTileY;
uniform float flipbookChannelPacked;
uniform float flipbookDurationMs;
uniform float flipbookDelayMs;
uniform float flipbookLoop;
uniform float flipbookFrameIntervalMs;
uniform float flipbookSegmentedLoop;
uniform float flipbookLoopStartFrame;
uniform float flipbookLoopFrameCount;
uniform float flipbookLoopFrameIntervalMs;
uniform float flipbookLoopStartMs;
uniform float flipbookOpacity;
uniform float sampleCurrentTexture;
uniform float directAtlasSample;
uniform float cardCutoutEnabled;
uniform float cardCutoutSoftness;
uniform float packedEnergyColorizeEnabled;
uniform float colorAdjustEnabled;
uniform float hueShift;
uniform float saturationMul;
uniform float valueMul;
uniform float contrastMul;
uniform float colorAdjustStrength;
uniform float colorAdjustWhiteProtect;
uniform float colorAdjustMode;
uniform float colorFlipbookFrameCount;
uniform float colorFlipbookFrameStart;
uniform float colorFlipbookTileX;
uniform float colorFlipbookTileY;
uniform float colorFlipbookChannelPacked;
uniform float colorMix;

float getFlipbookCellIndexEx(float frameIdx, float channelPacked) {
  if (channelPacked > 0.5) {
    return floor(frameIdx / 4.0);
  }
  return frameIdx;
}

float getFlipbookCellIndex(float frameIdx) {
  return getFlipbookCellIndexEx(frameIdx, flipbookChannelPacked);
}

vec4 getFlipbookChannelEx(float frameIdx, float channelPacked) {
  if (channelPacked < 0.5) {
    return vec4(1.0);
  }
  float ch = mod(frameIdx, 4.0);
  if (ch < 0.5) {
    return vec4(1.0, 0.0, 0.0, 0.0);
  }
  if (ch < 1.5) {
    return vec4(0.0, 1.0, 0.0, 0.0);
  }
  if (ch < 2.5) {
    return vec4(0.0, 0.0, 1.0, 0.0);
  }
  return vec4(0.0, 0.0, 0.0, 1.0);
}

vec4 getFlipbookChannel(float frameIdx) {
  return getFlipbookChannelEx(frameIdx, flipbookChannelPacked);
}

vec2 clampAtlasLocalUv(vec2 localUv, float tileX, float tileY, vec4 atlasSize, float paddingPx) {
  float safeTileX = max(1.0, floor(tileX + 0.5));
  float safeTileY = max(1.0, floor(tileY + 0.5));
  vec2 safeAtlasSize = max(atlasSize.xy, vec2(safeTileX * 2.0, safeTileY * 2.0));
  vec2 cellPx = max(vec2(1.0, 1.0), safeAtlasSize / vec2(safeTileX, safeTileY));
  vec2 halfTexel = 0.5 / cellPx;
  vec2 padUv = min(vec2(max(0.0, paddingPx)) / cellPx, vec2(0.45, 0.45));
  vec2 minUv = padUv + halfTexel;
  vec2 maxUv = vec2(1.0, 1.0) - padUv - halfTexel;
  return mix(minUv, maxUv, clamp(localUv, 0.0, 1.0));
}

vec2 getFlipbookAtlasUvEx(float frameIdx, vec2 localUv, float tileX, float tileY, float channelPacked, vec4 atlasSize, float paddingPx) {
  float safeTileX = max(1.0, floor(tileX + 0.5));
  float safeTileY = max(1.0, floor(tileY + 0.5));
  float cellIdx = getFlipbookCellIndexEx(frameIdx, channelPacked);
  float col = mod(cellIdx, safeTileX);
  float row = floor(cellIdx / safeTileX);
  float rowClamped = clamp(row, 0.0, safeTileY - 1.0);
  vec2 cell = vec2(1.0 / safeTileX, 1.0 / safeTileY);
  vec2 safeLocalUv = clampAtlasLocalUv(localUv, safeTileX, safeTileY, atlasSize, paddingPx);
  return vec2(
    (col + safeLocalUv.x) * cell.x,
    (rowClamped + safeLocalUv.y) * cell.y
  );
}

vec2 getFlipbookAtlasUv(float frameIdx, vec2 localUv, float tileX, float tileY) {
  return getFlipbookAtlasUvEx(frameIdx, localUv, tileX, tileY, flipbookChannelPacked, flipbookAtlasSize, flipbookAtlasPadding.x);
}

float remapPackedEnergyAlpha(float alpha) {
  float energyAlpha = clamp(alpha, 0.0, 1.0);

  if (flipbookMaskRemap.y >= 0.5) {
    return energyAlpha;
  }
  float low = clamp(flipbookAtlasPadding.z, 0.0, 0.98);
  float high = clamp(max(flipbookAtlasPadding.w, low + 0.001), 0.001, 1.0);
  float remapped = smoothstep(low, high, energyAlpha);
  float gammaValue = max(0.001, flipbookMaskRemap.x);
  return pow(remapped, gammaValue);
}

vec2 getSourceUvFromSpriteUv(vec2 localUv) {
  return localUv;
}

float getSourceCropMaskForRect(vec2 sourceUv, vec4 cropRect) {
  vec2 cropMin = clamp(cropRect.xy, vec2(0.0, 0.0), vec2(1.0, 1.0));
  vec2 cropMax = clamp(cropRect.xy + max(cropRect.zw, vec2(0.0001, 0.0001)),
    vec2(0.0, 0.0), vec2(1.0, 1.0));
  vec2 insideMin = step(cropMin, sourceUv);
  vec2 insideMax = step(sourceUv, cropMax);
  return insideMin.x * insideMin.y * insideMax.x * insideMax.y;
}

vec2 getAtlasLocalUvFromSourceUvForRect(vec2 sourceUv, vec4 cropRect) {
  vec2 cropMin = clamp(cropRect.xy, vec2(0.0, 0.0), vec2(1.0, 1.0));
  vec2 cropSize = max(cropRect.zw, vec2(0.0001, 0.0001));
  return clamp((sourceUv - cropMin) / cropSize, vec2(0.0, 0.0), vec2(1.0, 1.0));
}

float getSourceCropMask(vec2 sourceUv) {
  return getSourceCropMaskForRect(sourceUv, flipbookSourceCropRect);
}

vec2 getAtlasLocalUvFromSourceUv(vec2 sourceUv) {
  return getAtlasLocalUvFromSourceUvForRect(sourceUv, flipbookSourceCropRect);
}

vec4 sampleFlipbookFrame(float frameIdx, vec2 localUv, float tileX, float tileY) {
  vec2 sourceUv = getSourceUvFromSpriteUv(localUv);
  float cropMask = getSourceCropMask(sourceUv);
  vec2 atlasLocalUv = getAtlasLocalUvFromSourceUv(sourceUv);
  vec4 texel = texture2D(flipbookTex, getFlipbookAtlasUv(frameIdx, atlasLocalUv, tileX, tileY));
  if (flipbookChannelPacked < 0.5) {
    return texel * cropMask;
  }
  float value = dot(texel, getFlipbookChannel(frameIdx));
  value = remapPackedEnergyAlpha(value);
  return vec4(vec3(value), value) * cropMask;
}

vec4 sampleColorFlipbookFrame(float frameIdx, vec2 localUv) {
  float safeSegmentFrameCount = max(1.0, floor(colorFlipbookFrameCount + 0.5));
  float safeFrameStart = max(0.0, floor(colorFlipbookFrameStart + 0.5));
  float safeLocalIdx = clamp(frameIdx, 0.0, safeSegmentFrameCount - 1.0);
  float safeFrameIdx = safeFrameStart + safeLocalIdx;
  vec2 sourceUv = getSourceUvFromSpriteUv(localUv);
  float cropMask = getSourceCropMaskForRect(sourceUv, colorFlipbookSourceCropRect);
  vec2 atlasLocalUv = getAtlasLocalUvFromSourceUvForRect(sourceUv, colorFlipbookSourceCropRect);
  vec4 texel = texture2D(colorFlipbookTex, getFlipbookAtlasUvEx(safeFrameIdx, atlasLocalUv,
    max(1.0, colorFlipbookTileX), max(1.0, colorFlipbookTileY), colorFlipbookChannelPacked, colorFlipbookAtlasSize, flipbookAtlasPadding.y));
  if (colorFlipbookChannelPacked < 0.5) {
    return texel * cropMask;
  }
  float value = dot(texel, getFlipbookChannelEx(safeFrameIdx, colorFlipbookChannelPacked));
  return vec4(vec3(value), value) * cropMask;
}

vec3 rgbToYiq(vec3 rgb) {
  return vec3(
    dot(rgb, vec3(0.299, 0.587, 0.114)),
    dot(rgb, vec3(0.596, -0.274, -0.322)),
    dot(rgb, vec3(0.211, -0.523, 0.312))
  );
}

vec3 yiqToRgb(vec3 yiq) {
  return clamp(vec3(
    yiq.x + 0.956 * yiq.y + 0.621 * yiq.z,
    yiq.x - 0.272 * yiq.y - 0.647 * yiq.z,
    yiq.x - 1.106 * yiq.y + 1.703 * yiq.z
  ), 0.0, 1.0);
}

vec3 applyPsHueYiq(vec3 rgb, float hueShiftVal) {
  vec3 yiq = rgbToYiq(max(rgb, vec3(0.0)));
  float chroma = length(yiq.yz);
  float hue = chroma > 1.0e-5 ? atan(yiq.z, yiq.y) : 0.0;
  hue += hueShiftVal * 6.28318530718;
  yiq.yz = vec2(cos(hue), sin(hue)) * chroma;
  return yiqToRgb(yiq);
}

vec3 applyPsSaturationRec709(vec3 rgb, float sat) {
  float s = max(0.0, sat);
  vec3 safe = max(rgb, vec3(0.0));
  float luma = dot(safe, vec3(0.2125, 0.7154, 0.0721));
  return mix(vec3(luma), safe, s);
}

float bakedRec709Luminance(vec3 rgb) {
  return dot(max(rgb, vec3(0.0)), vec3(0.2126, 0.7152, 0.0722));
}

float calcHighlightPreserveMask(float bright, float protect) {
  float band = mix(0.02, 0.08, clamp(protect, 0.0, 2.0) * 0.5);
  return smoothstep(1.0 - band, 1.0, clamp(bright, 0.0, 1.0));
}

vec3 applyHighlightPreservingValueScale(vec3 sourceRgb, float valueMul, float strength) {
  float s = clamp(strength, 0.0, 1.0);
  float mul = max(0.0, valueMul);
  vec3 safe = max(sourceRgb, vec3(0.0));
  if (s <= 0.00001 || abs(mul - 1.0) <= 0.00001) {
    return safe;
  }
  float protect = clamp(colorAdjustWhiteProtect, 0.0, 2.0);
  if (protect <= 0.00001) {
    return mix(safe, clamp(safe * mul, 0.0, 1.0), s);
  }
  float luma = bakedRec709Luminance(safe);
  float peak = max(max(safe.r, safe.g), safe.b);
  float bright = max(luma, peak);
  float preserve = calcHighlightPreserveMask(bright, protect);
  float yScaled = clamp(luma * mul, 0.0, 1.0);
  vec3 chroma = safe - luma;
  vec3 adjusted = clamp(yScaled + chroma, 0.0, 1.0);
  vec3 preserved = mix(adjusted, safe, preserve);
  return mix(safe, preserved, s);
}

vec3 applyRuntimeBakedHueSatAdjust(vec3 sourceRgb) {
  float strength = clamp(colorAdjustStrength, 0.0, 1.0);
  vec3 safe = max(sourceRgb, vec3(0.0));
  vec3 hued = applyPsHueYiq(safe, hueShift);
  vec3 satd = applyPsSaturationRec709(hued, saturationMul);
  return mix(safe, satd, strength);
}

vec3 applyRuntimeBakedContrastAdjust(vec3 sourceRgb) {
  float s = clamp(colorAdjustStrength, 0.0, 1.0);
  float mul = max(0.0, contrastMul);
  vec3 safe = max(sourceRgb, vec3(0.0));
  if (s <= 0.00001 || abs(mul - 1.0) <= 0.00001) {
    return safe;
  }
  float luma = bakedRec709Luminance(safe);
  float newLuma = clamp((luma - 0.5) * mul + 0.5, 0.0, 1.0);
  vec3 contrasted = clamp(vec3(newLuma) + (safe - luma), 0.0, 1.0);
  return mix(safe, contrasted, s);
}

vec3 applyRuntimeBakedValueAdjust(vec3 sourceRgb) {
  if (colorAdjustMode > 0.5) {
    float strength = clamp(colorAdjustStrength, 0.0, 1.0);
    vec3 safe = max(sourceRgb, vec3(0.0));
    if (strength <= 0.00001 || abs(valueMul - 1.0) <= 0.00001) {
      return safe;
    }
    vec3 adj = clamp(safe + vec3(valueMul - 1.0), 0.0, 1.0);
    return mix(safe, adj, strength);
  }
  return applyHighlightPreservingValueScale(sourceRgb, valueMul, colorAdjustStrength);
}

float sampleFlipbookEnergy(float frameIdx, vec2 localUv, float tileX, float tileY) {
  return sampleFlipbookFrame(frameIdx, localUv, tileX, tileY).a;
}

vec3 applyLobeGradientDetail(vec3 rgb, float energy, vec2 localUv, float frameIdx0, float frameIdx1, float frameBlend, float tileX, float tileY) {
  vec2 atlasCell = max(flipbookAtlasSize.xy / vec2(max(1.0, tileX), max(1.0, tileY)), vec2(1.0));
  vec2 texel = vec2(1.0) / atlasCell;
  float eL = mix(sampleFlipbookEnergy(frameIdx0, localUv - vec2(texel.x, 0.0), tileX, tileY),
    sampleFlipbookEnergy(frameIdx1, localUv - vec2(texel.x, 0.0), tileX, tileY), frameBlend);
  float eR = mix(sampleFlipbookEnergy(frameIdx0, localUv + vec2(texel.x, 0.0), tileX, tileY),
    sampleFlipbookEnergy(frameIdx1, localUv + vec2(texel.x, 0.0), tileX, tileY), frameBlend);
  float eB = mix(sampleFlipbookEnergy(frameIdx0, localUv - vec2(0.0, texel.y), tileX, tileY),
    sampleFlipbookEnergy(frameIdx1, localUv - vec2(0.0, texel.y), tileX, tileY), frameBlend);
  float eT = mix(sampleFlipbookEnergy(frameIdx0, localUv + vec2(0.0, texel.y), tileX, tileY),
    sampleFlipbookEnergy(frameIdx1, localUv + vec2(0.0, texel.y), tileX, tileY), frameBlend);
  float grad = (abs(eR - eL) + abs(eT - eB)) * 0.5;
  float lobe = smoothstep(0.025, 0.15, grad) * smoothstep(0.15, 0.85, energy);
  vec3 detail = mix(maskOuterColor.rgb, maskInnerColor.rgb, 0.42);
  vec3 brightened = max(rgb, detail * 0.85);
  return mix(brightened, detail, lobe * 0.38);
}

vec3 colorizePackedEnergy(float energy) {
  float edge = smoothstep(0.012, 0.14, energy);
  float mid = smoothstep(0.08, 0.50, energy);
  float inner = smoothstep(0.30, 0.68, energy);
  float core = smoothstep(0.76, 0.94, energy);
  vec3 edgeRgb = maskOuterColor.rgb * 0.35;
  vec3 midRgb = mix(maskOuterColor.rgb, maskInnerColor.rgb, 0.48);
  vec3 innerRgb = mix(maskInnerColor.rgb, vec3(1.0), 0.32);
  vec3 coreRgb = vec3(1.0);
  vec3 rgb = mix(edgeRgb, midRgb, mid);
  rgb = mix(rgb, innerRgb, inner);
  rgb = mix(rgb, coreRgb, core * 0.58);
  return rgb * max(edge, 0.90);
}

void main() {
  vec2 uvSize = max(uvRect.zw, vec2(0.0001, 0.0001));
  vec2 localUv = clamp((v_uv0 - uvRect.xy) / uvSize, 0.0, 1.0);
  float safeFrameCount = max(1.0, floor(flipbookFrameCount + 0.5));
  float safeTileX = max(1.0, floor(flipbookTileX + 0.5));
  float safeTileY = max(1.0, floor(flipbookTileY + 0.5));
  float safeDurationSec = max(0.001, flipbookDurationMs * 0.001);
  float delaySec = max(0.0, flipbookDelayMs * 0.001);
  if (time < delaySec) {
    discard;
  }

  float elapsedSec = max(0.0, time - delaySec);
  float frameFloat = 0.0;
  float frameIdx0 = 0.0;
  float frameIdx1 = 0.0;
  float loopStart = clamp(floor(flipbookLoopStartFrame + 0.5), 0.0, safeFrameCount - 1.0);
  float loopCount = clamp(floor(flipbookLoopFrameCount + 0.5), 0.0, safeFrameCount - loopStart);
  float intervalMs = max(1.0, flipbookFrameIntervalMs);
  if (flipbookSegmentedLoop > 0.5 && loopCount > 1.0) {
    float elapsedMs = elapsedSec * 1000.0;
    float loopStartMs = flipbookLoopStartMs > 0.0 ? flipbookLoopStartMs : loopStart * intervalMs;
    float loopIntervalMs = max(1.0, flipbookLoopFrameIntervalMs);
    if (elapsedMs < loopStartMs || loopStart < 1.0) {
      float introLast = max(0.0, loopStart - 1.0);
      frameFloat = clamp(elapsedMs / intervalMs, 0.0, introLast);
      frameIdx0 = clamp(floor(frameFloat), 0.0, safeFrameCount - 1.0);
      frameIdx1 = clamp(ceil(frameFloat), 0.0, safeFrameCount - 1.0);
    } else {
      float loopFrameFloat = max(0.0, elapsedMs - loopStartMs) / loopIntervalMs;
      float loopBase = mod(floor(loopFrameFloat), loopCount);
      frameFloat = loopStart + loopBase + fract(loopFrameFloat);
      frameIdx0 = loopStart + loopBase;
      frameIdx1 = loopStart + mod(loopBase + 1.0, loopCount);
    }
  } else if (flipbookLoop > 0.5 && loopCount > 1.0) {

    float elapsedMs = elapsedSec * 1000.0;
    float loopIntervalMs = max(1.0, flipbookLoopFrameIntervalMs > 0.0 ? flipbookLoopFrameIntervalMs : intervalMs);
    float periodFrames = min(loopCount, safeFrameCount);
    float loopFrameFloat = elapsedMs / loopIntervalMs;
    float loopBase = mod(floor(loopFrameFloat), periodFrames);
    frameFloat = loopBase + fract(loopFrameFloat);
    frameIdx0 = mod(loopBase, safeFrameCount);
    frameIdx1 = mod(loopBase + 1.0, safeFrameCount);
  } else {

    float elapsedMs = elapsedSec * 1000.0;
    frameFloat = clamp(elapsedMs / intervalMs, 0.0, safeFrameCount - 1.0);
    frameIdx0 = clamp(floor(frameFloat), 0.0, safeFrameCount - 1.0);
    frameIdx1 = clamp(ceil(frameFloat), 0.0, safeFrameCount - 1.0);
  }
  float frameBlend = fract(frameFloat);
  vec4 frame0 = sampleFlipbookFrame(frameIdx0, localUv, safeTileX, safeTileY);
  vec4 frame1 = sampleFlipbookFrame(frameIdx1, localUv, safeTileX, safeTileY);
  float blendedAlpha = mix(frame0.a, frame1.a, frameBlend);
  vec3 premulRgb = mix(frame0.rgb * frame0.a, frame1.rgb * frame1.a, frameBlend);
  vec4 flipbookColor = vec4(premulRgb / max(blendedAlpha, 0.0001), blendedAlpha) * v_color;
  if (directAtlasSample > 0.5) {
    vec2 directUv = directAtlasRect.xy + localUv * max(directAtlasRect.zw, vec2(0.0001, 0.0001));
    flipbookColor = texture2D(flipbookTex, directUv) * v_color;
  }
  if (sampleCurrentTexture > 0.5) {
    flipbookColor = texture2D(texture, v_uv0);
    #if CC_USE_ALPHA_ATLAS_TEXTURE
      flipbookColor.a *= texture2D(texture, v_uv0 + vec2(0.0, 0.5)).r;
    #endif
    flipbookColor *= v_color;
  }
  float flameEnergy = -1.0;
  if (flipbookChannelPacked > 0.5 && flipbookColor.a > 0.001) {
    flameEnergy = clamp(flipbookColor.a, 0.0, 1.0);
  }
  if (packedEnergyColorizeEnabled > 0.5 && flameEnergy >= 0.0) {
    vec3 packedRgb = colorizePackedEnergy(flameEnergy);
    packedRgb = applyLobeGradientDetail(packedRgb, flameEnergy, localUv, frameIdx0, frameIdx1, frameBlend, safeTileX, safeTileY);
    flipbookColor.rgb = packedRgb * v_color.rgb;
  }
  if (colorAdjustEnabled > 0.5 && flipbookColor.a > 0.001) {
    flipbookColor.rgb = applyRuntimeBakedHueSatAdjust(flipbookColor.rgb);
  }
  if (colorMix > 0.001) {
    vec4 color0 = sampleColorFlipbookFrame(frameIdx0, localUv);
    vec4 color1 = sampleColorFlipbookFrame(frameIdx1, localUv);
    float colorAlpha = mix(color0.a, color1.a, frameBlend);
    vec3 colorRgb = mix(color0.rgb * color0.a, color1.rgb * color1.a, frameBlend) / max(colorAlpha, 0.0001);
    vec4 colorSample = vec4(colorRgb, colorAlpha) * v_color;
    if (colorAdjustEnabled > 0.5 && colorSample.a > 0.001) {
      colorSample.rgb = applyRuntimeBakedHueSatAdjust(colorSample.rgb);
    }
    float colorAlphaWeight = smoothstep(0.002, 0.08, colorSample.a)
      * smoothstep(0.002, 0.08, flipbookColor.a);
    flipbookColor.rgb = mix(flipbookColor.rgb, colorSample.rgb, clamp(colorMix, 0.0, 1.0) * colorAlphaWeight);
  }
  if (colorAdjustEnabled > 0.5 && flipbookColor.a > 0.001) {
    flipbookColor.rgb = applyRuntimeBakedContrastAdjust(flipbookColor.rgb);
  }
  if (colorAdjustEnabled > 0.5 && flipbookColor.a > 0.001) {
    flipbookColor.rgb = applyRuntimeBakedValueAdjust(flipbookColor.rgb);
  }
  float outAlpha = flipbookColor.a * clamp(flipbookOpacity, 0.0, 1.0);
  if (cardCutoutEnabled > 0.5) {
    vec2 cutMin = clamp(cardCutoutRect.xy, vec2(0.0, 0.0), vec2(1.0, 1.0));
    vec2 cutMax = clamp(cardCutoutRect.xy + cardCutoutRect.zw, vec2(0.0, 0.0), vec2(1.0, 1.0));
    float soft = max(0.0001, cardCutoutSoftness);
    float insideX = smoothstep(cutMin.x - soft, cutMin.x + soft, localUv.x)
      * (1.0 - smoothstep(cutMax.x - soft, cutMax.x + soft, localUv.x));
    float insideY = smoothstep(cutMin.y - soft, cutMin.y + soft, localUv.y)
      * (1.0 - smoothstep(cutMax.y - soft, cutMax.y + soft, localUv.y));
    outAlpha *= (1.0 - insideX * insideY);
  }
  if (outAlpha <= 0.001) {
    discard;
  }

  vec4 outColor = vec4(flipbookColor.rgb, outAlpha);
  gl_FragColor = outColor;
}
